package br.com.social.post; import jakarta.persistence.*; @Entity @Table(name="post_likes",uniqueConstraints=@UniqueConstraint(columnNames={"post_id","user_email"})) public class PostLike{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="post_id",nullable=false)private Long postId;@Column(name="user_email",nullable=false)private String userEmail;public PostLike(){}public PostLike(Long p,String e){postId=p;userEmail=e;}public Long getId(){return id;}public Long getPostId(){return postId;}public String getUserEmail(){return userEmail;}}